import React from 'react';
import { Layout, Avatar, Row, Col } from 'antd';
import Chat from './components/Chat';
// Dashboard será importado depois
// import Dashboard from './components/Dashboard';

const { Header, Content } = Layout;

function App() {
  return (
    <Layout style={{ minHeight: '100vh', background: '#fafbfc' }}>
      <Header style={{ background: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'space-between', boxShadow: '0 2px 8px #f0f1f2', position: 'fixed', width: '100%', zIndex: 10, top: 0, left: 0, height: 64 }}>
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <img src="https://uploads-ssl.webflow.com/5e5e1c2e6e6b6c1b1c8b4567/5e5e1c2e6e6b6c2b1c8b4568_logo-cortex.svg" alt="cortex logo" style={{ height: 32, marginRight: 12 }} />
          <span style={{ fontWeight: 700, fontSize: 24, color: '#222' }}>cortex</span>
        </div>
        <Avatar style={{ background: '#e6e6e6', color: '#888' }}>WM</Avatar>
      </Header>
      <Content style={{ display: 'flex', justifyContent: 'center', alignItems: 'flex-start', minHeight: '100vh', paddingTop: 64, background: '#fafbfc' }}>
        <Row style={{ width: '100%', maxWidth: 1400, minHeight: 'calc(100vh - 64px)' }} gutter={32}>
          <Col span={16} style={{ height: 'calc(100vh - 64px)', display: 'flex', flexDirection: 'column' }}>
            {/* <Dashboard /> */}
            <div style={{ background: '#fff', borderRadius: 12, boxShadow: '0 2px 12px #e6e6e6', flex: 1, overflowY: 'auto', minHeight: 400, padding: 24 }}>
              <div style={{ color: '#bbb', textAlign: 'center', marginTop: 100 }}>[Dashboard aqui]</div>
            </div>
          </Col>
          <Col span={8} style={{ height: 'calc(100vh - 64px)', display: 'flex', flexDirection: 'column' }}>
            <Chat />
          </Col>
        </Row>
      </Content>
    </Layout>
  );
}

export default App;
